head.script:
scwin.init = function() {
    grd.setColumnStyle(0, 'background-color', 'yellow');
};
scwin.test = function(row, col, text) {
    alert(row + " " + col + " " + text);
}
scwin.gridView1_onbeforesort = function(sortInfo) {
    //debugger;
    return false;
};
scwin.setSimulate1 = function() {
    WebSquare.wUnit.getJq('#grd_cell_0_0').simulate('keydown', {
        key: 'ENTER',
        keyCode: 13,
        code: 13
    });
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1.
    //1.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grd_cell_0_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    // verify step 1.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grd_cell_0_2').css('background-color') == 'rgb(252, 167, 60)'", "true");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {
    scwin.init();
    ecxelprint = function() {
        window.options = {
            common: {
                fileName: "user.xls",
                showProcess: true,
                printSet: {
                    landScape: "true",
                    fitToPage: "true",
                    fitWidth: "1",
                    fitHeight: "1",
                    scale: "222"
                }
            },
            excelInfo: [{
                gridId: "grid1",
                sheetName: "첫번째 sheet",
                type: "1",
                removeColumns: "1,3",
                foldColumns: "2",
                startRowIndex: 3,
                startColumnIndex: 0,
                headerColor: "#DBEEF3",
                bodyColor: "#92CDDC",
                dataProvider: "com.provider.Provider1",
                providerRequestXml: "<info><key value='TEST'/><info>",
                infoArr: [{
                    rowIndex: 1,
                    colIndex: 3,
                    rowSpan: 1,
                    colSpan: 2,
                    text: "데이터표시",
                    textAlign: "center"
                }]
            }]
        }
        WebSquare.util.multipleExcelDownload(options);
    };
    test = function() {
        //해더 갯수
        //debugger;
        window.headerCnt = gridView1.getTotalHeaderCol();
        window.headerIdList = [];
        for (var i = 0; i < headerCnt; i++) {
            //헤더 컬럼명
            window.headerId = gridView1.getHeaderID(i);
            window.frue_false = eval("gridView1_" + headerId).getAttribute("sortable");
            if (frue_false == "true") {
                console.log("true 일때");
                headerIdList.push(headerId);
            } else if (frue_false == "false") {
                console.log("false 일때");
                headerIdList.push(headerId);
            }
        }
        console.log(headerIdList);
        for (var idx = 0; idx < headerIdList.length; idx++) {
            window.frue_false = eval("gridView1_" + headerId).getAttribute("sortable");
            if (frue_false == "true") {
                console.log("true 일때");
                eval("gridView1_" + headerIdList[idx]).setAttribute("sortable", "false");
            } else if (frue_false == "false") {
                console.log("false 일때");
                eval("gridView1_" + headerIdList[idx]).setAttribute("sortable", "true");
            }
        }
    }
    fn_focus = function() {
        alert();
    };
}
